mapper.select:
SELECT obj."id" AS id, obj."streamId" AS stream_id, obj."data" ->> 'units' AS units, obj."data" ->> 'category' AS category, obj."data" ->> 'family' AS family, obj."data" ->> 'type' AS type, obj."data" ->> 'elementId' AS elementId, obj."data" ->> 'parameters' AS parameters, obj."data" ->> 'speckle_type' AS speckle_type, obj."data" ->'definition'->>'referencedId' AS referencedId FROM objects obj WHERE obj."id" IN ( SELECT jsonb_object_keys ( obj."data" -> '__closure' ) FROM objects obj WHERE obj."id" = ( SELECT info -> 'commit' ->> 'objectId' AS objectId FROM stream_activity WHERE "resourceId" = #{resourceId} AND "actionType" = 'commit_create' ) )
AND obj."data" ->> 'category' = #{category}
AND obj."data" ->'definition'->>'referencedId' IS NOT NULL
